const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const adirondacks = ee.Geometry.Polygon([
    [-74.5, 44.0], [-73.5, 44.0], [-73.5, 43.5], [-74.5, 43.5], [-74.5, 44.0]
  ]);

  const date1 = '2022-10-01';
  const date2 = '2022-10-08';

  // Function to mask clouds in Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate brown/orange index (higher values = more brown/orange)
  function calcBrownIndex(image) {
    return image.normalizedDifference(['B04', 'B03']).rename('brown_index'); // (Red - Green)/(Red + Green)
  }

  // 2. Data Acquisition
  const s2_col1 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(adirondacks)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .map(maskS2Clouds);

  const s2_col2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(adirondacks)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .map(maskS2Clouds);

  const size1 = s2_col1.size().getInfo();
  const size2 = s2_col2.size().getInfo();

  print(`Oct 1 Images: ${size1}, Oct 8 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get first (least cloudy) images
  const img1 = s2_col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2 = s2_col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Calculate brown indices
  const brown1 = calcBrownIndex(img1);
  const brown2 = calcBrownIndex(img2);

  // Count pixels with brown_index > 0.1 (brown/orange areas)
  const brownMask1 = brown1.gt(0.1);
  const brownMask2 = brown2.gt(0.1);

  // Get pixel counts
  const count1 = brownMask1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: adirondacks,
    scale: 1000,
    maxPixels: 1e9
  }).get('brown_index').getInfo();

  const count2 = brownMask2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: adirondacks,
    scale: 1000,
    maxPixels: 1e9
  }).get('brown_index').getInfo();

  print(`Oct 1 brown pixels: ${count1}, Oct 8 brown pixels: ${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for invalid results
  if (count1 === null || count2 === null || isNaN(count1) || isNaN(count2)) {
    print("<answer>C3</answer>");
    return;
  }

  // Compare and output answer
  const percentChange = ((count2 - count1) / count1 * 100).toFixed(1);
  print(`Change: ${percentChange}%`);

  if (count2 > count1) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
